/**
 * Helper utilities for user-scoped browser storage.
 * Ensures strict data isolation between accounts so a new user never sees
 * articles, reports, or stats generated by another account.
 */

export function getUserStorageKey(baseKey: string, userId?: string | null): string {
  if (userId && typeof userId === 'string') {
    return `${baseKey}_${userId}`;
  }
  return `${baseKey}_guest`;
}

export function clearLegacyUserData(): void {
  if (typeof window === 'undefined') return;
  const legacyKeys = [
    'generated_articles',
    'content_schedule',
    'hero_keyword_reports',
    'brand_profile',
    'saved_marketing_assets',
    'website_audit_history',
    'hero_bookmarks',
  ];
  for (const key of legacyKeys) {
    try {
      localStorage.removeItem(key);
    } catch {
      // ignore
    }
  }
}

/**
 * Migrates legacy un-scoped articles to admin's user key if needed,
 * while ensuring new non-admin users start with a clean slate.
 */
export function migrateLegacyArticlesIfAdmin(userId: string, isAdmin: boolean): void {
  if (typeof window === 'undefined' || !userId) return;
  const userKey = getUserStorageKey('generated_articles', userId);

  if (isAdmin) {
    const existingUserArticles = localStorage.getItem(userKey);
    const legacyArticles = localStorage.getItem('generated_articles');
    if (!existingUserArticles && legacyArticles) {
      try {
        localStorage.setItem(userKey, legacyArticles);
        localStorage.removeItem('generated_articles');
      } catch {
        // ignore
      }
    }
  } else {
    // If a non-admin user logs in, remove legacy articles so they never leak into view
    try {
      localStorage.removeItem('generated_articles');
    } catch {
      // ignore
    }
  }
}
